local function a() return debug.traceback() end
local function b() return a() end
print(b())
print(debug.traceback("msg"))
print(debug.traceback("msg", 2))
print(debug.traceback(12))
print(debug.traceback({}) == nil, type(debug.traceback({})))
print(debug.traceback(nil))
print(select('#', debug.traceback(nil)))
print(debug.traceback(nil, 1))
print(debug.traceback("lvl0", 0))
print(debug.traceback("lvl50", 50))
local co = coroutine.create(function(x)
  local y = x + 1
  coroutine.yield(y)
  error("dead")
end)
coroutine.resume(co, 1)
print(debug.traceback(co))
print(debug.traceback(co, "comsg"))
print(debug.traceback(co, "comsg", 1))
print(debug.traceback(co, {}))
print(debug.getinfo(co, 0, "Sl").currentline, debug.getinfo(co, 1, "Sl").currentline, debug.getinfo(co, 2))
print(debug.getlocal(co, 1, 1), debug.getlocal(co, 1, 2))
print(debug.setlocal(co, 1, 2, 99), debug.getlocal(co, 1, 2))
print(pcall(debug.getlocal, co, 5, 1))
print(debug.getinfo(co, print, "S").what)
print(coroutine.resume(co))
print(debug.traceback(co))
local function deep(n) if n == 0 then return debug.traceback("deep") end return (deep(n - 1)) end
print(deep(30))
print(debug.traceback(coroutine.create(print)))
